//! Replays the guards' share of the oracle corpus: every case of a kind this
//! crate answers must get the answer upstream's TypeScript gave, compared as
//! text. The corpus is regenerated by `tools/oracle/refresh.sh`; nothing
//! here needs upstream or Bun.

use std::fs;
use std::path::Path;

use focus_guards::oracle::{KINDS, run_case};
use focus_js::json::stringify;
use serde_json::{Value, json};

#[test]
fn every_guard_case_gets_upstreams_answer() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.lines().filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let (mut replayed, mut stood_aside, mut held, mut pinned, mut refused, mut shell) =
        (0, 0, 0, 0, 0, 0);
    let (mut commands, mut fired) = (0, 0);
    let (mut scoped, mut blocked, mut defaulted) = (0, 0, 0);
    let (mut transitions, mut direct, mut boundary, mut delegated) = (0, 0, 0, 0);
    let (mut typed, mut switched, mut unreadable, mut asked, mut worded, mut split) =
        (0, 0, 0, 0, 0, 0);
    let (mut operations, mut rendered, mut matched, mut continued, mut admitted, mut remedies) =
        (0, 0, 0, 0, 0, 0);
    let (mut dispatches, mut dispatch_blocked, mut defective, mut appendix) = (0, 0, 0, 0);
    let (mut reasons, mut questions, mut approved, mut pending, mut plans, mut appended) =
        (0, 0, 0, 0, 0, 0);
    let (mut routes, mut routed, mut helpers, mut helper_may) = (0, 0, 0, 0);
    let (mut waits, mut prerequisite, mut directed, mut repo, mut diagnostic) = (0, 0, 0, 0, 0);
    let (mut lines, mut plain, mut faithful, mut dynamic) = (0, 0, 0, 0);
    let (mut intents, mut opaque, mut clear, mut engine, mut unread, mut spoken) =
        (0, 0, 0, 0, 0, 0);
    let (mut judged, mut outside, mut output, mut answer, mut diary, mut proposal) =
        (0, 0, 0, 0, 0, 0);
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        let case: Value = focus_js::json::parse(line).unwrap();
        let kind = case["kind"].as_str().unwrap_or_default();
        if !KINDS.contains(&kind) {
            continue;
        }
        // A shell case reads its command from a scratch root under `/tmp`,
        // where the directories it names exist: on Windows there is no such
        // root, and a destination that is a directory would not be one. An
        // integrity case lays its project tree there too, and reads paths
        // as the host does, so its answers are the POSIX host's; so does the
        // reviewer scope, whose `toPosix` and `path.resolve` are the host's,
        // and a mutation case, whose project is laid out there with links.
        if cfg!(windows)
            && matches!(
                kind,
                "shell_targets"
                    | "write_targets"
                    | "runtime_integrity"
                    | "reviewer_scope"
                    | "mutation_intent"
                    | "mutation_target"
            )
        {
            continue;
        }
        replayed += 1;
        shell += usize::from(kind.starts_with("shell_"));
        let out = run_case(&case);
        if kind == "engine_command" {
            commands += 1;
            fired += usize::from(out["classify"] == "fire");
        }
        if kind == "reviewer_scope" {
            scoped += 1;
            blocked += usize::from(out["verdict"]["block"] == true);
            defaulted += usize::from(out["verdict"]["defaulted"] == true);
        }
        if kind == "typed_switch" {
            typed += 1;
            switched += usize::from(out["switches"].as_array().is_some_and(|s| !s.is_empty()));
            unreadable += usize::from(!out["error"].is_null());
            asked += usize::from(out["asked"] == true);
            worded += usize::from(!out["words"].is_null());
        }
        if kind == "kiro_args" {
            split += 1;
        }
        if kind == "state_transition" {
            transitions += 1;
            direct += usize::from(!out["direct"].is_null());
            boundary += usize::from(out["boundary"] == true);
            delegated += usize::from(!out["delegated"].is_null());
        }
        if kind == "guard_operation" {
            operations += 1;
            let op = case["op"].as_str().unwrap_or_default();
            rendered += usize::from(op == "render" && out.is_string());
            matched += usize::from(op == "matches_command" && out == true);
            continued += usize::from(op == "continuation" && out.is_object());
            admitted += usize::from(op == "engine_invocation" && out == true);
            remedies += usize::from(op == "wording" && out.is_object());
        }
        if kind == "plan_dispatch" {
            dispatches += 1;
            dispatch_blocked += usize::from(out["block"] == true);
            defective += usize::from(!out["handoff"].is_null());
            appendix += usize::from(out["appendixInBrief"] == true);
        }
        reasons += usize::from(kind == "plan_reason" || kind == "contract_markers");
        if kind == "questions_file" {
            questions += 1;
            approved += usize::from(out["approved"] == true);
            pending += usize::from(out["pending"] == true);
        }
        if kind == "engine_route" {
            routes += 1;
            routed += usize::from(out.is_object());
        }
        if kind == "mutation_intent" {
            let intent = &out["intent"];
            intents += 1;
            opaque += usize::from(intent["opaqueShell"] == true);
            clear +=
                usize::from(intent["opaqueShell"] == false && intent["shellCommand"].is_string());
            engine += usize::from(intent["runsFocus"] == true);
            unread += usize::from(intent["readable"] == false);
            spoken += usize::from(out["person"]["spoke"] == true);
        }
        for target in out
            .as_array()
            .into_iter()
            .flatten()
            .filter(|_| kind == "mutation_target")
        {
            judged += 1;
            outside += usize::from(target["outside"] == true);
            output += usize::from(target["output"] == true);
            answer += usize::from(target["answer"] == true);
            diary += usize::from(target["diary"] == true);
            proposal += usize::from(target["composer"] == true);
        }
        if kind == "every_helper" {
            helpers += 1;
            helper_may += usize::from(out == true);
        }
        if matches!(
            kind,
            "plan_prerequisite" | "engine_directed" | "read_only_diagnostic"
        ) {
            waits += 1;
            prerequisite += usize::from(kind == "plan_prerequisite" && out == true);
            directed += usize::from(out["directed"] == true);
            repo += usize::from(out["repo"] == true);
            diagnostic += usize::from(out["diagnostic"] == true || out["tool"] == true);
        }
        if kind == "plain_powershell" {
            lines += 1;
            plain += usize::from(out["plain"].is_object());
            faithful += usize::from(out["reading"].is_string());
        }
        dynamic += usize::from(kind == "dynamic_evaluation" && out == true);
        if kind == "review_appendix" {
            plans += 1;
            appended += usize::from(out.as_str().is_some_and(|text| !text.is_empty()));
        }
        if let Some(decisions) = out["decisions"].as_array() {
            stood_aside += decisions
                .iter()
                .filter(|d| d["decision"] == "stand-aside")
                .count();
            held += decisions.iter().filter(|d| d["decision"] == "hold").count();
        }
        pinned += usize::from(!out["policy"]["memoryStrict"].is_null());
        refused += usize::from(!out["error"].is_null());
        let got = stringify(&json!({ "id": case["id"], "out": out }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    assert!(replayed >= 200, "too few guard cases: {replayed}");
    assert!(shell >= 500, "too few shell cases: {shell}");
    assert!(
        commands >= 300 && fired >= 50,
        "too few engine command cases: {commands}, {fired} of them transition tools"
    );
    assert!(
        cfg!(windows) || (scoped >= 500 && blocked >= 100 && defaulted >= 30),
        "too few reviewer scope cases: {scoped}, {blocked} blocked, {defaulted} on an implied root"
    );
    assert!(
        transitions >= 2000 && direct >= 100 && boundary >= 90 && delegated >= 1000,
        "too few state transition cases: {transitions}, {direct} direct, {boundary} at a boundary, {delegated} delegated"
    );
    assert!(
        typed >= 1000
            && switched >= 150
            && unreadable >= 15
            && asked >= 15
            && worded >= 250
            && split >= 300,
        "too few typed switch cases: {typed}, {switched} switches, {unreadable} unreadable, {asked} asked, {worded} with words; {split} word splits"
    );
    assert!(
        operations >= 1500
            && rendered >= 80
            && matched >= 100
            && continued >= 8
            && admitted >= 15
            && remedies >= 60,
        "too few guard operation cases: {operations}, {rendered} rendered, {matched} commands matched, {continued} continuations, {admitted} admitted, {remedies} worded"
    );
    assert!(
        dispatches >= 400 && dispatch_blocked >= 100 && defective >= 80 && appendix >= 3,
        "too few plan dispatch cases: {dispatches}, {dispatch_blocked} blocked, {defective} defective handoffs, {appendix} quoting the appendix"
    );
    assert!(
        reasons >= 700
            && questions >= 300
            && approved >= 30
            && pending >= 10
            && plans >= 300
            && appended >= 100,
        "too few posture cases: {reasons} reasons and markers, {questions} questions files ({approved} approved, {pending} pending), {plans} plans ({appended} with an appendix)"
    );
    assert!(
        routes >= 1000 && routed >= 500 && helpers >= 1000 && helper_may >= 250,
        "too few dispatcher cases: {routes} routes, {routed} delegated; {helpers} helper lines, {helper_may} admitted"
    );
    assert!(
        waits >= 1100 && prerequisite >= 100 && directed >= 80 && repo >= 6 && diagnostic >= 90,
        "too few plan-wait cases: {waits}, {prerequisite} prerequisites, {directed} engine-directed, {repo} repo changes, {diagnostic} diagnostics"
    );
    assert!(
        cfg!(windows)
            || (intents >= 2400
                && opaque >= 1400
                && clear >= 800
                && engine >= 1300
                && unread >= 400
                && spoken >= 900),
        "too few mutation cases: {intents}, {opaque} opaque, {clear} read whole and clear, {engine} running the engine, {unread} not read whole, {spoken} with the person on record"
    );
    assert!(
        cfg!(windows)
            || (judged >= 1300
                && outside >= 240
                && output >= 240
                && answer >= 28
                && diary >= 22
                && proposal >= 12),
        "too few write targets: {judged}, {outside} outside the project, {output} record outputs, {answer} answer texts, {diary} diaries, {proposal} proposals"
    );
    assert!(
        lines >= 600 && plain >= 200 && faithful >= 120 && dynamic >= 80,
        "too few command-line cases: {lines} PowerShell lines, {plain} plain, {faithful} read as POSIX; {dynamic} dynamic"
    );
    assert!(
        stood_aside >= 100 && held >= 100 && pinned >= 20 && refused >= 10,
        "{stood_aside} {held} {pinned} {refused}"
    );
    assert!(
        differing.is_empty(),
        "{} guard cases differ from upstream:\n{}",
        differing.len(),
        differing.join("\n")
    );
}
